CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (
 id UUID PRIMARY KEY DEFAULT gen_random_uuid(), username VARCHAR(24) NOT NULL UNIQUE, email VARCHAR(254) NOT NULL UNIQUE,
 password_hash TEXT NOT NULL, display_name VARCHAR(40), avatar_url TEXT, banner_url TEXT,
 nickname_color VARCHAR(7) NOT NULL DEFAULT '#a78bfa' CHECK (nickname_color ~ '^#[0-9A-Fa-f]{6}$'),
 bio VARCHAR(500) NOT NULL DEFAULT '', steam_id VARCHAR(80), birth_date DATE, balance_cents BIGINT NOT NULL DEFAULT 0 CHECK(balance_cents>=0),
 staff_salary BIGINT NOT NULL DEFAULT 0 CHECK(staff_salary>=0), is_banned BOOLEAN NOT NULL DEFAULT FALSE,
 created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE TABLE IF NOT EXISTS roles (id TEXT PRIMARY KEY, title TEXT NOT NULL, rank INTEGER NOT NULL UNIQUE, is_project_owner BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS permissions (id TEXT PRIMARY KEY, description TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS role_permissions (role_id TEXT REFERENCES roles(id) ON DELETE CASCADE, permission_id TEXT REFERENCES permissions(id) ON DELETE CASCADE, PRIMARY KEY(role_id,permission_id));
CREATE TABLE IF NOT EXISTS user_roles (user_id UUID REFERENCES users(id) ON DELETE CASCADE, role_id TEXT REFERENCES roles(id) ON DELETE RESTRICT, assigned_by UUID REFERENCES users(id), assigned_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY(user_id,role_id));
CREATE TABLE IF NOT EXISTS rules (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), title TEXT NOT NULL, body TEXT NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0, updated_by UUID REFERENCES users(id), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS products (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', category TEXT NOT NULL CHECK(category IN ('rank','privilege','consumable','service','economy')), store TEXT NOT NULL CHECK(store IN ('main','staff')), price_cents BIGINT NOT NULL DEFAULT 0 CHECK(price_cents>=0), currency CHAR(3) NOT NULL DEFAULT 'EUR', discount_percent INTEGER NOT NULL DEFAULT 0 CHECK(discount_percent BETWEEN 0 AND 100), stock INTEGER, minecraft_command TEXT, active BOOLEAN NOT NULL DEFAULT TRUE, requires_staff BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS orders (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id), product_id UUID NOT NULL REFERENCES products(id), username_target VARCHAR(24) NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','paid','fulfilled','failed','refunded','cancelled')), amount_cents BIGINT NOT NULL, currency CHAR(3) NOT NULL, provider TEXT, provider_payment_id TEXT, payment_url TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), paid_at TIMESTAMPTZ, fulfilled_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS payment_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), provider TEXT NOT NULL, event_id TEXT NOT NULL UNIQUE, order_id UUID REFERENCES orders(id), payload JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS salary_transactions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id), actor_id UUID NOT NULL REFERENCES users(id), amount BIGINT NOT NULL CHECK(amount<>0), reason TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS privileges (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id), server_name TEXT NOT NULL DEFAULT 'Hypego', minecraft_username VARCHAR(24) NOT NULL, product_name TEXT NOT NULL, starts_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), expires_at TIMESTAMPTZ, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','expired','revoked','pending')), source_order UUID REFERENCES orders(id), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS delivery_jobs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), order_id UUID NOT NULL UNIQUE REFERENCES orders(id), status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','processing','done','failed')), attempts INTEGER NOT NULL DEFAULT 0, last_error TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS tickets (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id), subject VARCHAR(120) NOT NULL, body TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','in_progress','closed')), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS punishments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), target_username VARCHAR(24) NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('warn','mute','ban','unban','unmute')), reason TEXT NOT NULL, actor_id UUID NOT NULL REFERENCES users(id), expires_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS wall_posts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), profile_user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, author_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, body VARCHAR(500) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS friendships (user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, friend_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','rejected')), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY(user_id,friend_id), CHECK(user_id<>friend_id));
CREATE TABLE IF NOT EXISTS unban_appeals (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id), reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')), reviewed_by UUID REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS audit_logs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), actor_id UUID REFERENCES users(id), action TEXT NOT NULL, target_type TEXT, target_id TEXT, details JSONB NOT NULL DEFAULT '{}'::jsonb, ip_hash TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS orders_user_idx ON orders(user_id,created_at DESC);
CREATE INDEX IF NOT EXISTS privileges_user_idx ON privileges(user_id,status);
CREATE INDEX IF NOT EXISTS audit_logs_created_idx ON audit_logs(created_at DESC);
